ui('chronological snake alternates right and left vertical turns and opens a stay detail dialog',async()=>{const f=fixture();try{const names=['北京','上海','Paris','北京','上海','Paris','北京','上海'],role=f.state.characters[0];role.earthTravel={...f.w.IrisEarth.read(role),routes:Array.from({length:7},(_,i)=>({id:'segment-'+i,from:names[i],to:names[i+1],age:10+i,year:null,purpose:'可能因工作访问',basis:'职业相关的旅行推测',stay:i===2?'约3—5天':'',source:'人设',quote:'',status:'合理推演',confidence:.6,review:'confirmed'})).reverse()};f.mount();await flush();const lines=[...f.w.document.querySelectorAll('.earth-snake-line')];assert.equal(lines[0].getAttribute('d'),'M30 38 L150 38');assert.equal(lines[2].getAttribute('d'),'M270 38 L270 130');assert.equal(lines[5].getAttribute('d'),'M30 130 L30 222');const segment=f.q('[data-route-show="segment-2"]');segment.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'Enter',bubbles:true}));const dialog=f.q('dialog[open]');assert.ok(dialog);assert.match(dialog.textContent,/Paris.*北京/s);assert.match(dialog.textContent,/约3—5天/);assert.match(dialog.textContent,/工作访问/);assert.equal(f.q('.earth-ticket-info').hidden,true);f.q('[data-earth-ticket]').click();assert.equal(f.q('.earth-ticket-info').hidden,false);f.q('[data-earth-ticket]').click();assert.equal(f.q('.earth-ticket-info').hidden,true);assert.equal(f.q('.earth-trip-close'),null);f.q('.earth-trip-dialog').click();assert.equal(f.q('dialog'),null);f.q('[data-route-show="segment-0"]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));assert.match(f.q('dialog').textContent,/未记录/)}finally{f.close()}});
ui('global icon strokes do not outline snake city and date text',async()=>{const f=fixture();try{f.options.content.classList.add('earth-panel');const css=fs.readFileSync(__dirname+'/../style.css','utf8'),style=f.w.document.createElement('style');style.textContent=css.match(/}svg\{[^}]+\}/)[0].slice(1)+'\n'+css.split('/* SVG route text must not inherit the global icon stroke. */')[1];f.w.document.head.append(style);f.mount();await flush();f.q('[data-earth-generate]').click();await flush();for(const selector of ['.earth-snake','.earth-snake-city text','.earth-snake-time']){const computed=f.w.getComputedStyle(f.q(selector));assert.ok(['none','rgba(0, 0, 0, 0)'].includes(computed.stroke));assert.equal(computed.strokeWidth,'0')}assert.equal(f.w.getComputedStyle(f.q('.earth-snake-city text')).fontWeight,'400')}finally{f.close()}});
