ui('country anchors resolve the six reported cities without country metadata or route changes',async()=>{const f=fixture();try{const names=['杭州','曼彻斯特','伦敦','巴黎','爱丁堡','利物浦'],all=JSON.parse(fs.readFileSync(__dirname+'/../assets/earth-cities.json','utf8'));f.w.fetch=async()=>({ok:true,json:async()=>all.filter(c=>names.some(n=>c[6].includes(n)))});const role=f.state.characters[0];role.earthTravel={...f.w.IrisEarth.read(role),routes:names.slice(1).map((to,i)=>({id:'trip-'+i,from:names[i],to,age:18+i,year:null,date:(18+i)+'岁-06-15',purpose:'休假',status:'合理推演',confidence:.6,review:'confirmed'}))};const data=JSON.stringify(role.earthTravel);f.mount();await flush();assert.match(f.q('[data-earth-location-status]').textContent,/已定位 5 \/ 5 段/);f.q('[data-earth-review]').click();assert.match(f.q('[data-earth-review-result]').textContent,/补画 5 \/ 5 段/);assert.doesNotMatch(f.q('[data-earth-review-result]').textContent,/本次未绘制|本次未画/);assert.equal(f.calls(),0);assert.equal(JSON.stringify(role.earthTravel),data)}finally{f.close()}});
ui('the three reported legs resolve without Edinburgh, Liverpool or any country anchors',async()=>{const f=fixture();try{const names=['杭州','曼彻斯特','伦敦','曼彻斯特'],all=JSON.parse(fs.readFileSync(__dirname+'/../assets/earth-cities.json','utf8'));f.w.fetch=async()=>({ok:true,json:async()=>all.filter(c=>names.some(n=>c[6].includes(n)))});const role=f.state.characters[0];role.earthTravel={...f.w.IrisEarth.read(role),routes:names.slice(1).map((to,i)=>({id:'isolated-'+i,from:names[i],to,age:18+i,year:null,date:(18+i)+'岁-06-15',purpose:'休假',status:'合理推演',confidence:.6,review:'confirmed'}))};const before=JSON.stringify(role.earthTravel);f.mount();await flush();assert.match(f.q('[data-earth-location-status]').textContent,/已定位 3 \/ 3 段/);f.q('[data-earth-review]').click();assert.match(f.q('[data-earth-review-result]').textContent,/补画 3 \/ 3 段/);assert.equal(f.q('[data-earth-review-result] li'),null);assert.equal(JSON.stringify(role.earthTravel),before);assert.equal(f.calls(),0)}finally{f.close()}});
ui('review preserves active playback, fractional progress, speed and camera and keeps paused playback paused',async()=>{const f=fixture();try{f.mount();await flush();f.q('[data-earth-generate]').click();await flush();f.q('[data-earth-generate]').click();await flush();f.q('[data-earth-speed]').value='4';f.q('[data-earth-speed]').dispatchEvent(new f.w.Event('change'));f.q('[data-earth-play]').click();f.frame(100);f.frame(200);const seek=f.q('[data-earth-seek]'),before=Number(seek.value),renders=f.baseRenders(),calls=f.calls();assert.ok(before>0);f.q('[data-earth-review]').click();assert.equal(f.q('[data-earth-play]').getAttribute('aria-pressed'),'true');assert.equal(Number(seek.value),before);assert.equal(f.q('[data-earth-speed]').value,'4');assert.equal(f.baseRenders(),renders);f.frame(300);assert.ok(Number(seek.value)>before);f.q('[data-earth-play]').click();f.frame(400);const paused=seek.value;f.q('[data-earth-review]').click();assert.equal(f.q('[data-earth-play]').getAttribute('aria-pressed'),'false');f.frame(500);assert.equal(seek.value,paused);assert.equal(f.calls(),calls)}finally{f.close()}});
ui('one generation request returns routes and city mappings, including old journeys, without follow-up calls',async()=>{const f=fixture();try{const catalog=[['1','Beijing','CN','22',39.9,116.4,['北京']],['2','London','GB','ENG',51.5,-.12,['London','伦敦']],['3','London','CA','08',42.98,-81.24,['London','伦敦']]];f.w.fetch=async()=>({ok:true,json:async()=>catalog});const role=f.state.characters[0],old={id:'old',from:'伦敦',to:'北京',age:17,year:null,date:'17岁-06-15',purpose:'原旅行原因',stayDays:9,status:'合理推演',confidence:.6,review:'confirmed'};role.earthTravel={...f.w.IrisEarth.read(role),routes:[old]};let calls=0,finish;f.options.analyze=async(prompt,_role,request)=>{calls++;assert.equal(request.background,true);assert.equal(_role,role);assert.match(prompt,/同一次生成/);return new Promise(resolve=>finish=resolve)};f.mount();await flush();assert.equal(f.q('[data-earth-speed]').value,'4');f.q('[data-earth-generate]').click();await flush();assert.equal(calls,1);f.state.char=1;f.w.IrisEarthPage.unmount();finish({aliases:[{name:'伦敦',realCity:'London',countryCode:'GB',basis:'资料支持英国求学'}],routes:[{from:'北京',to:'伦敦',age:18,year:null,date:'18岁-06-15',stayDays:5,purpose:'求学',source:'人设',quote:'',status:'合理推演',confidence:.6,ticket:{flight:'IR208',gate:'A12',seat:'12A',cabin:'经济舱'}}]});await flush();assert.equal(calls,1);assert.equal(role.earthTravel.routes.length,2);assert.equal(role.earthTravel.routes[0].fromPlace.id,'2');assert.equal(role.earthTravel.routes[0].purpose,'原旅行原因');assert.equal(role.earthTravel.routes[0].stayDays,9);assert.equal(role.earthTravel.routes[1].toPlace.id,'2');assert.equal(role.earthTravel.routes[1].toPlace.latitude,51.5);assert.equal(f.state.characters[1].earthTravel,undefined);f.state.char=0;f.mount();await flush();f.q('[data-earth-review]').click();f.q('[data-earth-play]').click();f.frame(100);f.frame(200);assert.equal(calls,1)}finally{f.close()}});
ui('existing-route location completion can select a smaller namesake once and persists it without regenerating travel',async()=>{const f=fixture();try{f.w.fetch=async()=>({ok:true,json:async()=>[['1','Beijing','CN','22',39.9,116.4,['北京']],['2','London','GB','ENG',51.5,-.12,['伦敦']],['3','London','CA','08',42.98,-81.24,['伦敦']]]});const role=f.state.characters[0];role.earthTravel={...f.w.IrisEarth.read(role),routes:[{id:'old',from:'北京',to:'伦敦',age:18,year:null,date:'18岁-06-15',purpose:'探访',stayDays:7,status:'合理推演',confidence:.6,review:'confirmed'}]};let calls=0;f.options.analyze=async prompt=>{calls++;assert.match(prompt,/不生成或修改行程/);const items=JSON.parse(prompt.split('待定位城市及本批新行程上下文：')[1]);return{locations:items.map(p=>({key:p.key,id:'3',basis:'结合角色加拿大经历选择'}))}};f.mount();await flush();f.q('[data-earth-geocode]').click();await flush();assert.equal(calls,1);assert.equal(role.earthTravel.routes.length,1);assert.equal(role.earthTravel.routes[0].toPlace.country,'CA');assert.equal(role.earthTravel.routes[0].purpose,'探访');assert.equal(role.earthTravel.routes[0].stayDays,7);f.q('[data-earth-geocode]').click();await flush();assert.equal(calls,1);assert.equal(role.earthTravel.routes[0].toPlace.id,'3')}finally{f.close()}});

ui('globe pins track projected cities, hide the far side and open the matching ticket',async()=>{const f=fixture();try{f.mount();await flush();f.q('[data-earth-generate]').click();await flush();f.frame(100);const before=JSON.stringify(f.state.characters[0].earthTravel),layer=f.q('.earth-stage [data-earth-landmarks]');assert.ok(layer);assert.equal(f.q('.earth-landmarks'),null);const pins=[...layer.querySelectorAll('button')];assert.equal(pins.length,2);assert.ok(pins.some(p=>p.getAttribute('aria-label').includes('北京')));assert.ok(pins.some(p=>p.getAttribute('aria-label').includes('上海')));assert.ok(pins.every(p=>p.textContent===''));const pin=pins.find(p=>!p.hidden),left=pin.style.left;f.q('[data-earth-globe]').dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'ArrowLeft'}));f.frame(200);assert.notEqual(pin.style.left,left);pin.click();assert.ok(f.q('.earth-ticket-dialog[open]'));assert.equal(JSON.stringify(f.state.characters[0].earthTravel),before);for(let i=0;i<32;i++)f.q('[data-earth-globe]').dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'ArrowLeft'}));f.frame(300);assert.ok(pins.every(p=>p.hidden));assert.equal(f.calls(),1)}finally{f.close()}});
ui('ticket back generates all route memories in one Experiences call and persists per route',async()=>{const f=fixture();try{f.mount();await flush();f.q('[data-earth-generate]').click();await flush();f.q('[data-earth-generate]').click();await flush();f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));f.q('[data-earth-ticket]').click();f.q('[data-earth-memory-flip]').click();assert.equal(f.q('[data-earth-memory-generate]'),null);assert.equal(f.q('[data-earth-ticket-front]').hidden,true);assert.equal(f.q('[data-earth-memory-page]').hidden,false);let calls=0;f.options.analyze=async(prompt,role,request)=>{calls++;assert.equal(request.background,true);assert.equal(role,f.state.characters[0]);const tasks=JSON.parse(prompt.split('全部行程：')[1]);assert.equal(tasks.length,2);return{memories:tasks.map(t=>({id:t.id,type:t.type,title:t.from+'的片段',content:'收拾行李，记录这一天的旅途。',basis:'依据该段出行目的作日常推测。'}))}};assert.equal(f.q('[data-earth-generate]').nextElementSibling,f.q('[data-earth-generate-memories]'));assert.equal(f.q('[data-earth-memory-flip]').parentElement,f.q('.earth-route-actions'));f.q('[data-earth-generate-memories]').click();f.q('[data-earth-generate-memories]').click();await flush();assert.equal(calls,1);assert.equal(f.state.characters[0].earthTravel.routes.filter(r=>r.memory).length,2);assert.equal(f.q('[data-earth-memory-content] small'),null);assert.equal(f.q('[data-earth-memory-back]').parentElement,f.q('.travel-record-font-toolbar'));assert.equal(f.q('[data-earth-memory-content]').parentElement.className,'earth-memory-scroll');f.q('[data-earth-memory-back]').click();assert.equal(f.q('[data-earth-ticket-front]').hidden,false);f.q('.earth-trip-dialog').click();f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));f.q('[data-earth-ticket]').click();f.q('[data-earth-memory-flip]').click();assert.match(f.q('[data-earth-memory-content]').textContent,/收拾行李/);assert.equal(calls,1)}finally{f.close()}});
ui('incomplete memory generation leaves all saved routes unchanged',async()=>{const f=fixture();try{f.mount();await flush();f.q('[data-earth-generate]').click();await flush();const before=JSON.stringify(f.state.characters[0].earthTravel);f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));f.q('[data-earth-ticket]').click();f.q('[data-earth-memory-flip]').click();f.options.analyze=async()=>({memories:[]});f.q('[data-earth-generate-memories]').click();await flush();assert.equal(JSON.stringify(f.state.characters[0].earthTravel),before);assert.match(f.q('[data-earth-memory-status]').textContent,/未覆盖全部/);assert.equal(f.q('[data-earth-generate-memories]').disabled,false)}finally{f.close()}});
ui('top fragment button generates without opening any ticket and survives repeated clicks',async()=>{const f=fixture();try{f.mount();await flush();f.q('[data-earth-generate]').click();await flush();assert.equal(f.q('.earth-ticket-dialog'),null);let resolve,calls=0;f.options.analyze=async prompt=>{calls++;const tasks=JSON.parse(prompt.split('全部行程：')[1]);return new Promise(r=>resolve=()=>r({memories:tasks.map(t=>({id:t.id,type:t.type,title:'途中',content:'窗外的光影缓缓变换。',basis:'依据行程的日常推测。'}))}))};f.q('[data-earth-generate-memories]').click();f.q('[data-earth-generate-memories]').click();assert.equal(calls,1);assert.equal(f.q('[data-earth-generate-memories]').disabled,true);resolve();await flush();assert.ok(f.state.characters[0].earthTravel.routes[0].memory);assert.equal(f.q('[data-earth-generate-memories]').disabled,false);assert.match(f.q('[data-earth-feedback]').textContent,/已保存全部/);assert.equal(f.q('.earth-ticket-dialog'),null)}finally{f.close()}});
ui('together entry collects destination, departure and days and sends only through online invitation bridge',async()=>{const f=fixture();try{let sent;f.options.sendTravelInvitation=async(role,data)=>{sent={role,data}};f.mount();await flush();assert.equal(f.q('[data-earth-together]').nextElementSibling,f.q('[data-earth-generate]'));f.q('[data-earth-generate]').click();await flush();const before=JSON.stringify(f.state.characters[0].earthTravel),calls=f.calls();f.q('[data-earth-together]').click();assert.equal(f.q('[data-together-history]'),null);const form=f.q('[data-travel-invite-form]');form.elements.destination.value='上海';form.elements.departure.value='2026-11-01T09:00';form.elements.days.value='3';form.dispatchEvent(new f.w.Event('submit',{bubbles:true,cancelable:true}));await flush();assert.equal(sent.role,f.state.characters[0]);assert.deepEqual(JSON.parse(JSON.stringify(sent.data)),{destination:'上海',departure:'2026-11-01T09:00',days:3});assert.equal(JSON.stringify(f.state.characters[0].earthTravel),before);assert.equal(f.calls(),calls);assert.equal(f.q('.earth-travel-invite-dialog'),null)}finally{f.close()}});
ui('solo and shared S routes stay separate and shared routes belong to the current user',async()=>{const f=fixture();try{f.state.users=[{name:'用户甲',irisMarketId:'user-a'},{name:'用户乙',irisMarketId:'user-b'}];f.state.user=0;const role=f.state.characters[0];role.chatSettings={userIndex:0};const base={date:'2020-06-15',age:null,year:2020,purpose:'约定出行',status:'设定明确',confidence:1,review:'confirmed'};role.earthTravel={...f.w.IrisEarth.read(role),routes:[{...base,id:'solo-leg',from:'北京',to:'上海'},{...base,id:'shared-leg',from:'上海',to:'东京',sharedTravelFlight:true,sharedTravelId:'joint-a',sharedTravelUser:'user-a'},{...base,id:'other-user-leg',from:'巴黎',to:'伦敦',sharedTravelFlight:true,sharedTravelId:'joint-b',sharedTravelUser:'user-b'}]};f.options.sharedTripsFor=()=>[{id:'joint-a',destination:'东京',departure:'2020-06-15T09:00',days:3,statusLabel:'旅行中'}];f.mount();await flush();assert.equal(f.q('[data-earth-route-mode="solo"]').getAttribute('aria-pressed'),'true');assert.ok(f.q('[data-earth-routes] .earth-snake'));assert.ok(f.q('[data-route-id="solo-leg"]'));assert.equal(f.q('[data-route-id="shared-leg"]'),null);f.q('[data-earth-route-mode="shared"]').click();assert.equal(f.q('[data-earth-route-mode="shared"]').getAttribute('aria-pressed'),'true');assert.ok(f.q('[data-earth-routes] .earth-snake'));assert.ok(f.q('[data-route-id="shared-leg"]'));assert.equal(f.q('[data-route-id="solo-leg"]'),null);assert.equal(f.q('[data-route-id="other-user-leg"]'),null);assert.match(f.q('[data-earth-shared-trips]').textContent,/东京/);f.q('[data-earth-route-mode="solo"]').click();assert.ok(f.q('[data-route-id="solo-leg"]'));assert.equal(f.q('[data-earth-shared-trips]').hidden,true);assert.equal(role.earthTravel.routes.length,3)}finally{f.close()}});

ui('future shared flights use planned dashed S segments and keep planned labels',async()=>{const f=fixture();try{f.state.user=0;f.state.users=[{irisMarketId:'u1'}];const role=f.state.characters[0];role.chatSettings={userIndex:0};role.earthTravel={...f.w.IrisEarth.read(role),routes:[{id:'future-shared',from:'北京',to:'上海',date:'2035-12-10',age:null,year:2035,purpose:'未来计划',status:'设定明确',confidence:1,review:'confirmed',sharedTravelFlight:true,sharedTravelId:'future-trip',sharedTravelUser:'u1',plannedFlight:true}]};f.options.sharedTripsFor=()=>[{id:'future-trip',destination:'上海',departure:'2035-12-10T09:00',days:2,statusLabel:'攻略已确认'}];f.mount();await flush();f.q('[data-earth-route-mode="shared"]').click();assert.ok(f.q('[data-route-id="future-shared"].is-planned'));assert.match(f.q('[data-earth-routes]').textContent,/计划 · 2035-12-10/);assert.equal(f.q('[data-earth-route-mode="solo"]').getAttribute('aria-pressed'),'false')}finally{f.close()}});
ui('past shared flights remain solid when unfocused while future shared legs remain dashed',async()=>{
 const f=fixture();try{const role=f.state.characters[0],base={sharedTravelFlight:true,sharedTravelId:'shared',from:'北京',to:'上海',age:null,year:2027,date:'2027-01-01',review:'confirmed',status:'设定明确',confidence:1};role.earthTravel={...f.w.IrisEarth.read(role),routes:[{...base,id:'focus',plannedFlight:false},{...base,id:'past',from:'上海',to:'北京',plannedFlight:false},{...base,id:'future',plannedFlight:true,date:'2027-01-02'}]};const ctx=f.w.document.createElement('canvas').getContext('2d'),strokes=[];let dash=[];ctx.setLineDash=value=>{dash=Array.from(value)};const stroke=ctx.stroke;ctx.stroke=()=>{strokes.push({color:ctx.strokeStyle,width:ctx.lineWidth,dash:[...dash]});stroke()};f.mount();await flush();f.q('[data-earth-route-mode="shared"]').click();f.frame(100);const unfocused=strokes.filter(s=>s.color==='#929292'&&s.width===1.2);assert.ok(unfocused.some(s=>s.dash.length===0));assert.ok(unfocused.some(s=>s.dash.join(',')==='4,5'))}finally{f.close()}
});
