ui('single route generation saves valid travel despite missing ticket fields using one API call',async()=>{const f=fixture();try{let calls=0;f.options.analyze=async()=>{calls++;return{routes:[{from:'北京',to:'上海',age:18,year:null,date:'18岁-06-15',stayDays:5,purpose:'休假',source:'角色人设',quote:'',status:'合理推演',confidence:.6,ticket:{flight:'IR 208',gate:'待定',seat:null,cabin:'经济舱'}}]}};f.mount();await flush();f.q('[data-earth-generate]').click();await flush();assert.equal(calls,1);assert.equal(f.state.characters[0].earthTravel.routes.length,1);f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));assert.equal(f.q('.ticket-flight').textContent,'IR208');assert.equal(f.q('.ticket-seat').textContent,'—');assert.equal(f.q('.ticket-gate').textContent,'—');assert.equal(f.q('.ticket-stub-seat').textContent,'—')}finally{f.close()}});

ui('route generation accepts explanatory wrappers and keeps saved routes when a later response is truncated',async()=>{const f=fixture();try{const original=f.options.analyze;f.options.analyze=async()=> '以下是行程：\n```json\n'+JSON.stringify(await original())+'\n```\n整理完成。';f.mount();await flush();f.q('[data-earth-generate]').click();await flush();assert.equal(f.calls(),1);assert.equal(f.state.characters[0].earthTravel.routes.length,1);const before=JSON.stringify(f.state.characters[0].earthTravel);f.options.analyze=async()=> '说明：{"routes":[{"from":"北京"';f.q('[data-earth-generate]').click();await flush();assert.equal(JSON.stringify(f.state.characters[0].earthTravel),before);assert.match(f.q('[data-earth-feedback]').textContent,/截断|闭合/);assert.equal(f.q('[data-earth-generate]').disabled,false)}finally{f.close()}});

ui('single-route fragment rerolls rotate through 26 categories across remounts and display the actual category',async()=>{const f=fixture();try{f.mount();await flush();f.q('[data-earth-generate]').click();await flush();let calls=0;const types=[];f.options.analyze=async prompt=>{calls++;assert.match(prompt,/不能无论指定什么类型都写成泛泛的地点游记/);const tasks=JSON.parse(prompt.split('全部行程：')[1]);types.push(tasks[0].type);return{memories:tasks.map(t=>({id:t.id,type:t.type,title:'上海的片段',content:'角色记下一件具体的旅途小事。',basis:'依据角色出行条件合理推测。'}))}};for(let i=0;i<26;i++){if(i===13){f.w.IrisEarthPage.unmount();f.mount();await flush()}f.q('[data-earth-generate-memories]').click();await flush()}assert.equal(calls,26);assert.equal(new Set(types).size,26);assert.equal(f.state.characters[0].earthTravel.memoryCategoryPool.length,0);f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));f.q('[data-earth-ticket]').click();f.q('[data-earth-memory-flip]').click();assert.equal(f.q('[data-earth-memory-title]').textContent,types.at(-1));assert.notEqual(f.q('[data-earth-memory-title]').textContent,'上海的片段');const before=JSON.stringify(f.state.characters[0].earthTravel);f.options.analyze=async()=>{throw Error('request failed')};f.q('[data-earth-generate-memories]').click();await flush();assert.equal(JSON.stringify(f.state.characters[0].earthTravel),before)}finally{f.close()}});

ui('travel record font control imports URLs and files, switches globally, restores and deletes without altering app fonts',async()=>{const f=fixture();try{const faces=new Set();f.w.FontFace=class{constructor(family,source){this.family=family;this.source=source}async load(){return this}};Object.defineProperty(f.w.document,'fonts',{configurable:true,value:{ready:Promise.resolve(),add:face=>faces.add(face),delete:face=>faces.delete(face)}});f.mount();await flush();f.q('[data-earth-generate]').click();await flush();f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));f.q('[data-earth-ticket]').click();f.q('[data-earth-memory-flip]').click();assert.equal(f.q('[data-travel-record-font]').previousElementSibling,f.q('[data-earth-memory-back]'));f.q('[data-travel-record-font]').click();f.q('[data-font-url]').value='https://example.com/clear.woff2';f.q('[data-font-url-add]').click();await flush();const prefs=()=>f.state.settings.travelRecordFonts,style=()=>f.w.document.documentElement.style.getPropertyValue('--travel-record-font');assert.equal(prefs().fonts.length,1);assert.match(style(),/IrisTravelRecord/);assert.equal(f.w.document.documentElement.style.getPropertyValue('--mainFontFamily'),'');f.q('[data-font-choose="system"]').click();await flush();assert.match(style(),/system-ui/);f.q('[data-font-default]').click();await flush();assert.match(style(),/Zhi Mang Xing/);assert.equal(prefs().fonts.length,1);const input=f.q('[data-font-file]');Object.defineProperty(input,'files',{configurable:true,value:[new f.w.File(['font-bytes'],'personal.ttf',{type:'font/ttf'})]});await input.onchange({target:input});await flush();assert.equal(prefs().fonts.length,2);assert.match(prefs().fonts.at(-1).source,/^data:/);assert.match(style(),/IrisTravelRecord/);const selected=prefs().selected;f.q(`[data-font-delete="${selected}"]`).click();await flush();assert.equal(prefs().fonts.length,1);assert.equal(prefs().selected,'default');assert.match(style(),/Zhi Mang Xing/);assert.equal(faces.size,0);f.q('[data-font-close]').click();assert.equal(f.q('[data-travel-font-dialog]'),null)}finally{f.close()}});
ui('invalid or unloadable fonts and failed persistence keep previous travel font preferences',async()=>{const f=fixture();try{f.w.FontFace=class{constructor(family,source){this.family=family;this.source=source}async load(){if(this.source.includes('broken'))throw Error('font load failed');return this}};Object.defineProperty(f.w.document,'fonts',{configurable:true,value:{ready:Promise.resolve(),add(){},delete(){}}});f.mount();await flush();f.q('[data-earth-generate]').click();await flush();f.q('[data-route-show]').dispatchEvent(new f.w.MouseEvent('click',{bubbles:true}));f.q('[data-travel-record-font]').click();f.q('[data-font-url]').value='javascript:alert(1)';f.q('[data-font-url-add]').click();await flush();assert.equal(f.state.settings,undefined);f.q('[data-font-url]').value='https://example.com/broken.woff';f.q('[data-font-url-add]').click();await flush();assert.equal(f.state.settings,undefined);assert.match(f.q('[data-font-status]').textContent,/font load failed/);f.failSave(true);f.q('[data-font-choose="system"]').click();await flush();assert.equal(f.state.settings.travelRecordFonts,undefined);assert.match(f.w.document.documentElement.style.getPropertyValue('--travel-record-font'),/Zhi Mang Xing/);assert.equal(f.q('[data-font-choose="system"]').getAttribute('aria-pressed'),'false')}finally{f.close()}});
ui('travel fonts batch import keeps valid URLs and files, skips duplicates and preserves preferences on save failure',async()=>{
 const f=fixture();try{
  f.w.FontFace=class{constructor(family,source){this.family=family;this.source=source}async load(){if(this.source.includes('broken'))throw Error('字体不可加载');return this}};
  Object.defineProperty(f.w.document,'fonts',{configurable:true,value:{add(){},delete(){}}});
  const back=f.w.document.createElement('section');f.w.document.body.append(back);f.w.IrisTravelJournal.mountFontControl(back,{state:f.state,persist:f.options.persist});f.q('[data-travel-record-font]').click();
  const urls=f.q('[data-font-url]');assert.equal(urls.tagName,'TEXTAREA');
  urls.value='https://example.com/a.woff2\nfile:///broken.woff2\nhttps://example.com/b.woff2\nhttps://example.com/a.woff2\njavascript:bad';
  f.q('[data-font-url-add]').click();await flush();
  const prefs=()=>f.state.settings.travelRecordFonts;assert.equal(prefs().fonts.length,2);assert.equal(prefs().selected,prefs().fonts[0].id);assert.match(f.q('[data-font-status]').textContent,/已导入 2/);assert.match(f.q('[data-font-status]').textContent,/跳过 1/);assert.match(f.q('[data-font-status]').textContent,/broken/);assert.equal(f.persisted(),1);
  const input=f.q('[data-font-file]');assert.equal(input.multiple,true);
  Object.defineProperty(input,'files',{configurable:true,value:[new f.w.File(['first'],'first.ttf'),new f.w.File(['invalid'],'bad.txt'),new f.w.File(['second'],'second.otf')]});
  await input.onchange({target:input});assert.equal(prefs().fonts.length,4);assert.equal(f.persisted(),2);assert.match(f.q('[data-font-status]').textContent,/bad.txt/);
  const before=JSON.stringify(prefs());f.failSave(true);urls.value='https://example.com/c.woff2\nhttps://example.com/d.woff2';f.q('[data-font-url-add]').click();await flush();assert.equal(JSON.stringify(prefs()),before);assert.match(f.q('[data-font-status]').textContent,/未更改字体/);assert.equal(urls.disabled,false);
 }finally{f.close()}
});
ui('batch importing font URLs loads only the selected font and releases it on a switch',async()=>{
 const f=fixture();try{
  const loaded=[],faces=new Set();f.w.FontFace=class{constructor(family,source){this.family=family;this.source=source}async load(){loaded.push(this.source);return this}};Object.defineProperty(f.w.document,'fonts',{configurable:true,value:{add:face=>faces.add(face),delete:face=>faces.delete(face)}});
  const back=f.w.document.createElement('section');f.w.document.body.append(back);f.w.IrisTravelJournal.mountFontControl(back,{state:f.state,persist:f.options.persist});f.q('[data-travel-record-font]').click();f.q('[data-font-url]').value=Array.from({length:12},(_,i)=>`https://example.com/${i}.woff2`).join('\n');f.q('[data-font-url-add]').click();await flush();assert.equal(f.state.settings.travelRecordFonts.fonts.length,12);assert.equal(loaded.length,1);assert.equal(faces.size,1);
  const next=f.state.settings.travelRecordFonts.fonts[1];f.q(`[data-font-choose="${next.id}"]`).click();await flush();assert.equal(loaded.length,2);assert.equal(faces.size,1);f.q('[data-font-choose="system"]').click();await flush();assert.equal(faces.size,0);
 }finally{f.close()}
});
